//! `ips_detect`: subscribe to one camera's iceoryx2 images per thread, detect
//! ArUco (or, for calibration, AprilTag) markers with OpenCV, estimate each
//! marker's pose in the camera optical frame, and publish the detections over
//! zenoh as protobuf. The binary in `main.rs` drives these modules.

// sb-generated iceoryx2 subscriber for `ros2/sensor_msgs/Image1280x1024`.
// Do not edit, `sb sub edit` regenerates it. Its baked default key is this
// module's own; `camera` overrides `full` with the camera publisher's key.
#[path = "../swarmbotix_io/subscribers/image.rs"]
pub mod image;

// sb-generated zenoh publisher for `ros2/custom/MarkerDetections`. Do not edit.
// Encoding is the caller's job; we feed it prost bytes.
#[path = "../swarmbotix_io/publishers/markers.rs"]
pub mod markers_pub;

// sb-generated iceoryx2 publisher for `ros2/sensor_msgs/Image1280x1024Color`.
// Do not edit. When `debug: true` each camera publishes its annotated RGB frame
// here (one service per camera via the `module` override) for ips_viz.
#[path = "../swarmbotix_io/publishers/debug_image.rs"]
pub mod debug_image_pub;

// prost types for messages/custom/MarkerDetections.proto and CubePoses.proto
// (package swarmbotix.custom), generated by build.rs.
pub mod msgs {
    include!(concat!(env!("OUT_DIR"), "/swarmbotix.custom.rs"));
}

pub mod camera;
pub mod fps;
pub mod intrinsics;
pub mod markers;
pub mod view;
